function greet(name) {
  return `Hello, ${name}!`;
}

console.log(greet('JSVisualizer'));

function sum(numbers) {
  let total = 0;
  for (const n of numbers) {
    total += n;
  }
  return total;
}

console.log(sum([1, 2, 3, 4, 5]));

function fib(n) {
  if (n <= 1) return n;
  return fib(n - 1) + fib(n - 2);
}

console.log(fib(6));
